class ExamTracker {
    private List<Integer> times = new ArrayList<>();
    private List<Long> pre = new ArrayList<>(List.of(0L));
    public void record(int time, int score) {
        times.add(time);
        pre.add(pre.get(pre.size() - 1) + score);
    }
    public long totalScore(int startTime, int endTime) {
        int lo = 0, hi = times.size();
        while (lo < hi) { int m = (lo + hi) >>> 1;
            if (times.get(m) < startTime) lo = m + 1; else hi = m; }
        int l = lo; lo = 0; hi = times.size();
        while (lo < hi) { int m = (lo + hi) >>> 1;
            if (times.get(m) <= endTime) lo = m + 1; else hi = m; }
        return pre.get(lo) - pre.get(l);
    }
}

